/* Types */
export type AgentActionKind =
  | 'set_routing_mode'
  | 'set_tun_enabled'
  | 'set_system_proxy_enabled'
  | 'disable_stale_system_proxy';

export type AgentActionRequest =
  | { action: 'set_routing_mode'; mode: AgentRoutingMode }
  | { action: 'set_tun_enabled'; enabled: boolean }
  | { action: 'set_system_proxy_enabled'; enabled: boolean }
  | { action: 'disable_stale_system_proxy' };

export type AgentActionResult = {
  proposal_id: string;
  action: AgentActionKind;
  verified: boolean;
  snapshot: AgentNetworkSnapshot;
};

export type AgentActionRisk = 'traffic_change' | 'host_network_change';

export type AgentAppliedState = 'consistent' | 'stale' | 'unknown';

/**  Privacy-safe, read-only view: never expose proposal IDs or snapshot revisions. */
export type AgentAuditHistoryView = {
  retained_events: number;
  verified_events: number;
  entries: AgentAuditHistoryViewEntry[];
};

export type AgentAuditHistoryViewEntry = {
  recorded_at: number;
  action: string;
  outcome: string;
};

export type AgentConnectorState =
  'disconnected' | 'connecting' | 'connected' | 'unknown';

export type AgentCoreSnapshot = {
  state: AgentCoreState;
  run_type: AgentRunType;
  selected_core: string;
  state_changed_at: number;
  runtime_config_present: boolean;
  routing_mode: AgentRoutingMode | null;
  observed_routing_mode: AgentRoutingMode | null;
  applied_consistency: AgentAppliedState;
};

export type AgentCoreState = 'running' | 'stopped' | 'unknown';

/**  Read-only projection: do not expose revisions, targets, profile data, or secrets. */
export type AgentDiagnosticHistoryView = {
  retained_events: number;
  entries: AgentDiagnosticHistoryViewEntry[];
};

export type AgentDiagnosticHistoryViewEntry = {
  captured_at: number;
  health: string;
  core_state: string;
  service_state: string;
  finding_codes: string[];
  probe_failure_codes: string[];
};

export type AgentDiagnosticSummary = {
  revision: string;
  captured_at: number;
  health: AgentHealth;
  findings: AgentFinding[];
  probe_failures: AgentProbeFailure[];
  privacy: AgentPrivacyBoundary;
};

export type AgentFinding = {
  code: AgentFindingCode;
  severity: AgentFindingSeverity;
  recommended_action: AgentActionRequest | null;
};

export type AgentFindingCode =
  | 'weak_controller_secret'
  | 'system_proxy_without_running_core'
  | 'system_proxy_endpoint_mismatch'
  | 'runtime_config_missing'
  | 'active_profile_missing'
  | 'service_mode_inconsistent'
  | 'clash_connector_disconnected'
  | 'tun_runtime_mismatch'
  | 'recent_core_errors';

export type AgentFindingSeverity = 'info' | 'warning' | 'critical';

export type AgentHealth = 'healthy' | 'warning' | 'critical' | 'degraded';

export type AgentHostScope = 'loopback' | 'non_loopback' | 'unknown';

export type AgentImpact =
  | 'existing_connections_may_change'
  | 'traffic_may_bypass_proxy'
  | 'all_traffic_uses_proxy'
  | 'restore_rule_routing'
  | 'host_system_proxy_enabled'
  | 'host_system_proxy_disabled'
  | 'host_tun_enabled'
  | 'host_tun_disabled';

export type AgentIntent =
  | { intent: 'diagnose' }
  | { intent: 'set_routing_mode'; mode: AgentRoutingMode }
  | { intent: 'set_tun_enabled'; enabled: boolean }
  | { intent: 'set_system_proxy_enabled'; enabled: boolean }
  | { intent: 'disable_stale_system_proxy' };

export type AgentIntentRequest = {
  text: string;
};

export type AgentIntentResolution =
  | { status: 'resolved'; intent: AgentIntent }
  | { status: 'unsupported'; reason: AgentUnsupportedIntentReason };

export type AgentManifest = {
  schema_version: number;
  tools: AgentToolManifest[];
};

export type AgentNetworkProbeRequest = {
  url: string;
  expected_status: number | null;
  timeout_ms: number | null;
};

export type AgentNetworkProbeResult = {
  status: number;
  expected_status: number | null;
  matches_expected_status: boolean | null;
  latency_ms: number;
};

export type AgentNetworkSnapshot = {
  schema_version: number;
  revision: string;
  captured_at: number;
  app_version: string;
  os_family: string;
  health: AgentHealth;
  core: AgentCoreSnapshot;
  service: AgentServiceSnapshot;
  system_proxy: AgentSystemProxySnapshot;
  tun: AgentTunSnapshot;
  profiles: AgentProfileSnapshot;
  telemetry: AgentTelemetrySnapshot;
  findings: AgentFinding[];
  probe_failures: AgentProbeFailure[];
  privacy: AgentPrivacyBoundary;
};

export type AgentPrivacyBoundary = {
  contains_raw_logs: boolean;
  contains_profile_names: boolean;
  contains_profile_urls: boolean;
  contains_connection_targets: boolean;
  contains_controller_secret: boolean;
};

export type AgentProbeCode =
  | 'core_status_unavailable'
  | 'core_config_unavailable'
  | 'profiles_unavailable'
  | 'system_proxy_unavailable'
  | 'service_status_unavailable'
  | 'telemetry_unavailable';

export type AgentProbeFailure = {
  code: AgentProbeCode;
};

export type AgentProfileSnapshot = {
  total_count: number;
  active_count: number;
  remote_count: number;
  local_count: number;
  active_references_valid: boolean;
};

export type AgentProposal = {
  id: string;
  digest: string;
  action: AgentActionRequest;
  risk: AgentActionRisk;
  impacts: AgentImpact[];
  changes: AgentStateChange[];
  snapshot_revision: string;
  created_at: number;
  expires_at: number;
  requires_confirmation: boolean;
};

export type AgentRoutingMode = 'rule' | 'global' | 'direct';

export type AgentRunType = 'normal' | 'service' | 'elevated';

export type AgentServiceSnapshot = {
  desired_enabled: boolean;
  state: AgentServiceState;
  ipc_connected: boolean;
  runtime_compatible: boolean | null;
};

export type AgentServiceState =
  'not_installed' | 'stopped' | 'running' | 'unknown';

export type AgentStateChange = {
  field: string;
  before: string;
  after: string;
};

export type AgentSystemProxySnapshot = {
  desired_enabled: boolean;
  observed_enabled: boolean | null;
  observed_host_scope: AgentHostScope;
  observed_port: number | null;
  expected_mixed_port: number;
  matches_expected_endpoint: boolean | null;
};

export type AgentTelemetrySnapshot = {
  state: AgentConnectorState;
  active_connection_count: number | null;
  upload_speed: number | null;
  download_speed: number | null;
  upload_total: string | null;
  download_total: string | null;
  recent_error_count: number;
};

export type AgentToolManifest = {
  name: AgentToolName;
  version: number;
  description: string;
  risk: AgentToolRisk;
  read_only: boolean;
  timeout_ms: number;
  input_schema_version: number;
  output_schema_version: number;
};

export type AgentToolName =
  | 'system.snapshot'
  | 'network.diagnose'
  | 'network.probe'
  | 'core.status'
  | 'proxy.status'
  | 'tun.status'
  | 'profile.summary'
  | 'service.status';

export type AgentToolRequest =
  | { tool: 'system.snapshot' }
  | { tool: 'network.diagnose' }
  | { tool: 'network.probe'; arguments: AgentNetworkProbeRequest }
  | { tool: 'core.status' }
  | { tool: 'proxy.status' }
  | { tool: 'tun.status' }
  | { tool: 'profile.summary' }
  | { tool: 'service.status' };

export type AgentToolResult =
  | { tool: 'system.snapshot'; output: AgentNetworkSnapshot }
  | { tool: 'network.diagnose'; output: AgentDiagnosticSummary }
  | { tool: 'network.probe'; output: AgentNetworkProbeResult }
  | { tool: 'core.status'; output: AgentCoreSnapshot }
  | { tool: 'proxy.status'; output: AgentSystemProxySnapshot }
  | { tool: 'tun.status'; output: AgentTunSnapshot }
  | { tool: 'profile.summary'; output: AgentProfileSnapshot }
  | { tool: 'service.status'; output: AgentServiceSnapshot };

export type AgentToolRisk = 'read_only';

export type AgentTunSnapshot = {
  desired_enabled: boolean;
  generated_runtime_enabled: boolean | null;
  observed_active: AgentAppliedState;
  applied_consistency: AgentAppliedState;
};

export type AgentUnsupportedIntentReason =
  'empty_input' | 'input_too_long' | 'no_matching_intent';

export type AppUpdateChangelog = {
  /**  Newest first. */
  entries: AppUpdateChangelogEntry[];
  /**  `None` when either version is a nightly build, which has no tag. */
  compare_url: string | null;
};

export type AppUpdateChangelogEntry = {
  version: string;
  date: string | null;
  body: string;
  source: AppUpdateChangelogSource;
};

export type AppUpdateChangelogSource = 'changelog' | 'release';

export type AppUpdatePhase =
  | 'idle'
  | 'checking'
  | 'up_to_date'
  | 'available'
  | 'downloading'
  | 'cancelling'
  | 'cancelled'
  | 'verifying'
  | 'ready'
  | 'installing'
  | 'failed';

export type AppUpdateRelease = {
  version: string;
  date: string | null;
  body: string | null;
};

export type AppUpdateSnapshot = {
  revision: number;
  phase: AppUpdatePhase;
  release: AppUpdateRelease | null;
  downloaded: number;
  total: number | null;
  speed: number | null;
  source: UpdateSource | null;
  error: string | null;
  last_checked_at: string | null;
  supported: boolean;
  endpoints: string[];
};

export type AppUpdateStateChanged = AppUpdateSnapshot;

export type BreakConnectionStrategy = {
  /**  切换代理时中断连接 */
  on_proxy_change: ProxyChangeBreakMode;
  /**  切换配置时中断连接 */
  on_profile_change: boolean;
  /**  切换模式时中断连接 */
  on_mode_change: boolean;
};

export type BreakConnectionStrategyPatch =
  | BreakConnectionStrategyPatch_Serialize
  | BreakConnectionStrategyPatch_Deserialize;

export type BreakConnectionStrategyPatch_Deserialize = {
  on_proxy_change?: ProxyChangeBreakMode | null;
  on_profile_change?: boolean | null;
  on_mode_change?: boolean | null;
};

export type BreakConnectionStrategyPatch_Serialize = {
  on_proxy_change?: ProxyChangeBreakMode | null;
  on_profile_change?: boolean | null;
  on_mode_change?: boolean | null;
};

export type BreakWhenProxyChange = 'none' | 'chain' | 'all';

/**  Built-in post-processing steps applied to the selected config. */
export type BuiltinStepKind =
  /**  Kept for materializing older snapshots; new pipelines use fine-grained steps. */
  | 'guard_overrides'
  | 'whitelist_field_filter'
  /**  Restore unmanaged guard values removed by the first filter. */
  | 'keep_unmanaged'
  /**  Apply managed guard values, resolved ports, and routing-mark. */
  | 'managed_settings'
  /**  Restore unmanaged TUN values after guard settings (Chimera ordering). */
  | 'tun_keep_unmanaged'
  /**  Apply TUN enable/auto-route ownership before builtin transforms. */
  | 'tun_managed_settings'
  /**  Second field filter against the actual selected core's supported keys. */
  | 'final_field_filter'
  /**  Apply TUN, DNS and profile cache defaults after builtin transforms. */
  | 'defaults'
  /**  Expand legacy `include-all` proxy groups before final field sorting. */
  | 'include_all_expansion'
  | 'finalizing'
  /**  Read-only view of the configuration reported by the running core. */
  | 'core_controller';

export type Bytes = {
  upload: number;
  download: number;
};

